INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-B'), 'validierungsproben', 'Validierungsproben (gepaarte Zulauf-/Ablaufproben je Indikatororganismus)', 'json', NULL, false, '§3.3.3; Anhang C.2', 'Plan 3: Zeilen je Probenpaar (Organismus, Datum, x_i, y_i, Nachweisgrenzen-Flag); LRV_i, Tab.-3-Ziel, erreicht / Unterschreitung je Zeile; je Organismus n / n_erreicht / max. Unterschreitung / MW / SD / P10 / P50 / Verdikte (M12002-05-D…); ersetzt die Skalare x_i / y_i / lrv_i / log10_reduktionen / probenanzahl_zulauf / mw_log10 / sd_log10 (m1200_2-D-2 … -D-4); REQ-04 / -05 / -06 STAGED (m1200_2-G-1 / -G-2 / -G-7).', 'imported_unverified', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt: — I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — $\log _{10}$-Reduktion $=\log _{10}$ ( $C_{\text {Zulauf }} / C_{\text {Ablauf }}$ ) — Für den Fall, dass die Konzentration im Ablauf $C_{\text {Ablauf }}$ unterhalb der Nachweisgrenze ist, ist die $\log _{10}$ Reduktion mit der Nachweisgrenze zu ermitteln.', 'register', '{"title":"Validierungsproben (gepaart)","subtitle":"§3.3.3 / Anhang C.2 — je Indikatororganismus 16 korrespondierende Zulauf-/Ablaufproben; LRV_i = log10(x_i / y_i); liegt der Ablauf unter der Nachweisgrenze, die Nachweisgrenze als y_i eintragen (L1819) und \"Ablauf < 1 KBE/PFU\" markieren (Ziel gilt als erreicht, L681)","add_label":"+ Probenpaar","placement":"section","columns":[{"key":"organismus","label":"Indikatororganismus","type":"enum","required":true,"options":["e_coli","somatische_coliphagen","f_spez_coliphagen","clostridium","sulfatreduzierer"],"option_labels":{"e_coli":"E. coli","somatische_coliphagen":"somatische Coliphagen","f_spez_coliphagen":"f-spezifische Coliphagen","clostridium":"Clostridium-perfringens-Sporen","sulfatreduzierer":"sulfatreduzierende Sporenbildner"},"discriminator":true},{"key":"date","label":"Datum","type":"date","required":true},{"key":"x_i","label":"Zulauf x_i","type":"number","required":true,"min":0,"unit":"KBE bzw. PFU/100 ml","aria_label":"Zulaufkonzentration der Probe"},{"key":"y_i","label":"Ablauf y_i (bei < NWG: Nachweisgrenze)","type":"number","required":true,"min":0,"unit":"KBE bzw. PFU/100 ml","aria_label":"Ablaufkonzentration der Probe"},{"key":"below_detection","label":"Ablauf < 1 KBE bzw. PFU je 100 ml","type":"boolean"},{"key":"lrv_i","label":"LRV_i","type":"derived","expr":"log10(x_i / y_i)"},{"key":"ziel","label":"Leistungsziel (Tab. 3)","type":"derived","expr":"if(organismus == ''e_coli'', lookup(''TAB3'', wassergueteklasse, ''log10_e_coli''), if(organismus == ''somatische_coliphagen'', lookup(''TAB3'', wassergueteklasse, ''log10_somatische_coliphagen''), if(organismus == ''f_spez_coliphagen'', lookup(''TAB3'', wassergueteklasse, ''log10_f_coliphagen''), if(organismus == ''clostridium'', lookup(''TAB3'', wassergueteklasse, ''log10_clostridium''), lookup(''TAB3'', wassergueteklasse, ''log10_sulfatreduzierer'')))))"},{"key":"erreicht","label":"Ziel erreicht","type":"derived","expr":"if(below_detection == true OR lrv_i >= ziel, 1, 0)","display":"badge","value_labels":{"0":"nicht erreicht","1":"erreicht"}},{"key":"shortfall","label":"Unterschreitung","type":"derived","expr":"if(below_detection == true OR lrv_i >= ziel, 0, ziel - lrv_i)"}],"footer":["n_proben_validierung","validierung_ok_ecoli","validierung_ok_somat_coliphagen","validierung_ok_fspez_coliphagen","validierung_ok_clostridium","validierung_ok_sulfatreduzierer"],"note":"Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt:"}'::jsonb, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'validierungsproben') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'n_proben_validierung', 'Anzahl vollständiger Probenpaare (alle Organismen)', 'number', NULL, false, '§3.3.3', 'Plan 3: Ausgabe der Gleichung M12002-05-D1 (count_rows über validierungsproben); Übernahme als probenanzahl_zulauf / REQ-05 STAGED (m1200_2-D-3 / -G-1).', 'imported_unverified', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt:', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'n_proben_validierung') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
