SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'n_pass_min_tab', 'Mindestzahl erreichter Probenpaare nach §3.3.3 (A 15 · B-1/C-1 8 von 16)', 'number', NULL, false, '§3.3.3', 'Plan 3: Ausgabe der Gleichung M12002-05-D2 (lookup S3_3_3.n_pass_min zur geerbten Klasse; skalar, nicht materialisiert; keine Zeile für B-2 / C-2 / D).', 'imported_unverified', 'I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'n_pass_min_tab') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
