SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'perzentil_erforderlich', 'Gefordertes Perzentil der umfänglichen Validierung (A 10 · B-1/C-1 50)', 'number', NULL, false, 'Anhang C.1', 'Plan 3: Ausgabe der Gleichung M12002-05-D4 (lookup ANHANGC1.percentile; skalar, nicht materialisiert); REQ-06 (M12002-03) STAGED (m1200_2-G-2).', 'imported_unverified', 'I Klasse A: Das 10. Perzentil der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — I Klassen B-1 und C-1: Das 50. Perzentil (Median) der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen.', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'perzentil_erforderlich') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
