FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'p10_sulfatreduzierer_calc') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'p50_sulfatreduzierer_calc', '50. Perzentil (Median) — sulfatreduzierende Sporenbildner', 'number', 'log10', false, 'Anhang C.2, Gl. C.2-2', 'Plan 3: Ausgabe der Gleichung M12002-05-D48 (median_rows über die Zeilen des Organismus (L1823); Zeilen mit organismus = ''sulfatreduzierer'').', 'imported_unverified', '50. Perzentil = Median (Klassen B-1 und C-1)', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'p50_sulfatreduzierer_calc') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'validierung_ok_sulfatreduzierer', 'Vereinfachtes Validierungsmonitoring bestanden (1 = ja) — sulfatreduzierende Sporenbildner', 'number', NULL, false, '§3.3.3', 'Plan 3: Ausgabe der Gleichung M12002-05-D49 (≥ 16 Paare, ≥ 15 (A) / ≥ 8 (B-1, C-1) erreicht, größte Unterschreitung ≤ 1,0 / 2,0 log10 (S3_3_3; L681 / L683); ohne S3_3_3-Zeile (B-2, C-2, D) unentscheidbar; Zeilen mit organismus = ''sulfatreduzierer'').', 'imported_unverified', 'I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'validierung_ok_sulfatreduzierer') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-05-D'), 'perzentil_ok_sulfatreduzierer', 'Umfängliches Validierungsmonitoring: gefordertes Perzentil ≥ Leistungsziel (1 = ja) — sulfatreduzierende Sporenbildner', 'number', NULL, false, 'Anhang C.1 / C.2', 'Plan 3: Ausgabe der Gleichung M12002-05-D50 (10. Perzentil (A) bzw. Median (B-1, C-1) nach ANHANGC1 gegen das TAB3-Ziel (L1800 / L1802); Zeilen mit organismus = ''sulfatreduzierer'').', 'imported_unverified', 'I Klasse A: Das 10. Perzentil der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — I Klassen B-1 und C-1: Das 50. Perzentil (Median) der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen.', 'derived', NULL, NULL, 'wassergueteklasse IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'perzentil_ok_sulfatreduzierer') AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'validierungsmonitoring_typ IN {''umfaenglich'', ''umfaenglich_montecarlo''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'confidence_alpha' AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'validierungsmonitoring_typ IN {''umfaenglich'', ''umfaenglich_basis''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'k_faktor_normal' AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'wassergueteklasse == ''A''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'perzentil_10_log10' AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'wassergueteklasse IN {''B-1'', ''C-1''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'perzentil_50_log10' AND w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-06-B'), 'routineproben_1200_2', 'Routineproben (Datum, Parameter, Messwert → Einhaltung des Tab.-3-Werts)', 'json', NULL, false, '§3.1; §6.4', 'Plan 3: Zeilen je Routineprobe; Wert je Zeile aus TAB3 zur geerbten Wassergüteklasse (Zeilen-Scope — erreicht -06 erst nach der Konsumenten-Ergänzung m1200_2-C-1, bis dahin "kein Tab.-3-Wert"); Anteil eingehaltener Proben → konformitaet_calc (M12002-06-D1); ersetzt das manuell getippte perzentil_konformitaet (M12002-13) — STAGED (m1200_2-D-6 / -G-5); die Abweichungsgrenze (1 log10 / 100 %, L534 / L1283) ist nicht kodiert (Residuum).', 'imported_unverified', 'Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Für die Qualitätsüberwachung ist angelehnt an die EU-WasserWVVO, Anhang 1, Abschnitt 2, weiterhin gefordert, dass $90 \%$ der Proben die Mindestanforderungen gemäß Tabelle 3 einhalten müssen und die weiteren Proben eine maximale Überschreitung von $1 \log _{10}$-Stufe für E. coli und Legionellen bzw. $100 \%$ für andere Parameter aufweisen dürfen. Dies gilt vorbehaltlich gegebenenfalls weiterergehender Anforderungen, die aus dem Risikomanagementplan resultieren.', 'register', '{"title":"Routineproben (Stelle der Einhaltung)","subtitle":"§3.1 / §6.4 — je Probe Datum, Parameter, Messwert; Vergleich mit dem Tab.-3-Wert der Wassergüteklasse (Legionella strikt \"<\", sonst \"≤\"); Parameter ohne gedruckten Wert zählen nicht; die Klasse muss dieses Arbeitsblatt erreichen (m1200_2-C-1)","add_label":"+ Probe","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"parameter","label":"Parameter","type":"enum","required":true,"options":["e_coli","enterokokken","bsb5","afs","truebung","legionella","nematoden"],"option_labels":{"e_coli":"E. coli (KBE/100 ml)","enterokokken":"Intestinale Enterokokken (KBE/100 ml)","bsb5":"BSB5 (mg/l)","afs":"AFS (mg/l)","truebung":"Trübung (NTU)","legionella":"Legionella spp. (KBE/l)","nematoden":"Intestinale Nematoden (Eier/l)"},"discriminator":true},{"key":"wert","label":"Messwert","type":"number","required":true,"min":0,"aria_label":"Messwert der Probe"},{"key":"limit","label":"Wert nach Tab. 3","type":"derived","expr":"if(parameter == ''e_coli'', lookup(''TAB3'', wassergueteklasse, ''e_coli_max''), if(parameter == ''enterokokken'', lookup(''TAB3'', wassergueteklasse, ''enterokokken_max''), if(parameter == ''bsb5'', lookup(''TAB3'', wassergueteklasse, ''bsb5_max''), if(parameter == ''afs'', lookup(''TAB3'', wassergueteklasse, ''afs_max''), if(parameter == ''truebung'', lookup(''TAB3'', wassergueteklasse, ''truebung_max''), if(parameter == ''legionella'', lookup(''TAB3'', wassergueteklasse, ''legionella_max''), lookup(''TAB3'', wassergueteklasse, ''nematoden_max'')))))))"},{"key":"relevant","label":"Wert vorhanden","type":"derived","expr":"if(limit IS NULL, 0, 1)","display":"badge","value_labels":{"0":"kein Tab.-3-Wert (Klasse / Parameter)","1":""}},{"key":"ok","label":"eingehalten","type":"derived","expr":"if(limit IS NULL, 0, if(parameter == ''legionella'', if(wert < limit, 1, 0), if(wert <= limit, 1, 0)))","display":"badge","value_labels":{"0":"überschritten","1":"eingehalten"}}],"footer":["konformitaet_calc"],"note":"Für die Qualitätsüberwachung ist angelehnt an die EU-WasserWVVO, Anhang 1, Abschnitt 2, weiterhin gefordert, dass $90 \\%$ der Proben die Mindestanforderungen gemäß Tabelle 3 einhalten müssen und die weiteren Proben eine maximale Überschreitung von $1 \\log _{10}$-Stufe für E. coli und Legionellen bzw. $100 \\%$ für andere Parameter aufweisen dürfen. Dies gilt vorbehaltlich gegebenenfalls weiterergehender Anforderungen, die aus dem Risikomanagementplan resultieren."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'routineproben_1200_2') AND w.code = 'M12002-06' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-06-D'), 'konformitaet_calc', 'Anteil der Routineproben, die den Tab.-3-Wert einhalten (Soll ≥ 90 %)', 'number', '%', false, '§3.1; §6.4', 'Plan 3: Ausgabe der Gleichung M12002-06-D1 (count_rows(ok == 1) · 100 / count_rows(relevant == 1) über routineproben_1200_2; 100 = Prozent; keine Probe mit Wert ⇒ unentscheidbar, nie 0); Übernahme als perzentil_konformitaet / REQ-03 (M12002-13) STAGED (m1200_2-D-6 / -G-5).', 'imported_unverified', 'Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Für die Qualitätsüberwachung ist angelehnt an die EU-WasserWVVO, Anhang 1, Abschnitt 2, weiterhin gefordert, dass $90 \%$ der Proben die Mindestanforderungen gemäß Tabelle 3 einhalten müssen und die weiteren Proben eine maximale Überschreitung von $1 \log _{10}$-Stufe für E. coli und Legionellen bzw. $100 \%$ für andere Parameter aufweisen dürfen. Dies gilt vorbehaltlich gegebenenfalls weiterergehender Anforderungen, die aus dem Risikomanagementplan resultieren.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'konformitaet_calc') AND w.code = 'M12002-06' AND s.code = 'DWA-M-1200-2';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren IN {''mf'', ''uf'', ''mbr''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'mbr_porendurchmesser' AND w.code = 'M12002-09' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren == ''langsamsand''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'filtergeschw_langsam' AND w.code = 'M12002-09' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren IN {''raumfilter'', ''schnellsand''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'filtergeschw_schnellsand' AND w.code = 'M12002-09' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''uv''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'uv_dosis' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''uv''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'uv_dosis_referenz' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''ozon''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'ozon_dosis_spez' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'attestation', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren IN {''ozon'', ''chlor'', ''clo2'', ''pes'', ''pfa'', ''h2o2''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'reaktor_hydraulik_charakterisiert' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren IN {''chlor'', ''clo2''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'ct_wert' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''clo2''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'clo2_restkonz' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''pfa''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'perameisensaeure_konz' AND w.code = 'M12002-11' AND s.code = 'DWA-M-1200-2' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-12-B'), 'verfahrenskette_stufen', 'Verfahrenskette — Aufbereitungsstufen mit indikativen log10-Reduktionen (Tab. B.2), Betriebsparametern (Tab. 6) und Betriebsfenstern', 'json', NULL, false, '§3.3.2; §3.3.3; Anhang B, Tab. B.2; §6.4, Tab. 6', 'Plan 3: Zeilen je Aufbereitungsstufe (TABB2-Zeile; erreichbare log10 je Organismengruppe als überschreibbare Anhaltswerte, Begründung je Zeile; erwartbar / Tab. 6 / Tab. 4 / Tab. E.1 als Anzeige, null wo die Tabelle keine Zeile druckt); Σ Credits je Gruppe → credit_sum_* (M12002-12-D1 … -D3), Vergleich mit dem Tab.-3-Ziel → credit_ok_* (M12002-12-D4 … -D6, nur Hinweis); ersetzt das Freitextfeld verfahrenskette (m1200_2-D-7).', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — 2. Sofern keine Daten von Referenzanlagen vorliegen oder diese nicht anwendbar sind, können als Alternativvariante $\log _{10}$-Reduktionen und Betriebsdaten aus weiteren Quellen herangezogen werden, die den Anforderungen der Dokumentation als Referenzanlage nach 3.3.5 genügen (insbesondere im Hinblick auf die Festlegung adäquater Betriebsparameter). Diese Daten müssen durch eine unabhängige Einrichtung oder die Genehmigungsbehörde nach 3.3.5 begutachtet werden. Zu den weiteren Quellen für $\log _{10}$-Reduktionen und Betriebsdaten zählen beispielsweise technische Datenblätter von Lieferanten, veröffentlichte wissenschaftliche und technische Literatur (siehe z. B. die Zusammenstellung in Tabelle B. 1 im Anhang B), Leitlinien von Gesetzgebern (siehe z. B. die Australian Guidelines for Water Recycling (2006), die mit ergänzenden Angaben in Tabelle B. 2 im Anhang $B$ dargestellt sind) und historische Datenbestände von Anlagenbetreibern. Die einzelnen $\log _{10}$-Reduktionen werden anschließend über den gesamten Aufbereitungszug aufsummiert. — Tabelle B.2: Indikative $\log _{10}$-Reduktionen, denen Aufbereitungsstufen zuzuordnen sind (Australian Guidelines for Water Recycling, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, 2020), mit Ergänzungen zur Einordnung — Mit beiden Varianten werden die Mindestanforderungen an die Betriebsbedingungen für die Aufbereitungseinrichtung, insbesondere die relevanten Betriebsparameter und deren Anwendungsbereiche (Betriebsfenster) spezifiziert. Es sind mindestens die Betriebsparameter gemäß Tabelle 6 zu berücksichtigen. Hinweise zu relevanten Einflussfaktoren und relevanten Betriebsparametern können auch Tabelle 5 entnommen werden. Die spezifizierten Mindestanforderungen an die Betriebsparameter sind während der Inbetriebnahmephase und im Regelbetrieb einzuhalten.', 'register', '{"title":"Verfahrenskette (Aufbereitungsstufen)","subtitle":"Bild 1 / Anhang B — je Stufe die Tab.-B.2-Zeile; erreichbare log10-Reduktionen (indikativ, überschreibbar mit Referenzanlagen-Daten — bei \"abweichend\" alle drei Werte der Zeile eintragen, die Tabelle füllt eine abweichende Zeile nicht nach) werden über die Kette addiert; Tab.-6-Überwachung, Tab.-4-Validierungsmethodik und Tab.-E.1-Beispiel je Stufe, wo gedruckt","add_label":"+ Stufe","placement":"section","columns":[{"key":"reihenfolge","label":"Nr.","type":"number","required":true,"min":1,"aria_label":"Reihenfolge der Stufe"},{"key":"stufe","label":"Aufbereitungsstufe (Tab. B.2)","type":"lookup_key","required":true,"lookup":{"table_code":"TABB2"},"discriminator":true},{"key":"credit_viren","label":"log10 Viren (erreichbar)","type":"lookup_value","lookup":{"table_code":"TABB2","key_column":"stufe","value":"viren_erreichbar"}},{"key":"credit_protozoen","label":"log10 Protozoen (erreichbar)","type":"lookup_value","lookup":{"table_code":"TABB2","key_column":"stufe","value":"protozoen_erreichbar"}},{"key":"credit_bakterien","label":"log10 Bakterien (erreichbar)","type":"lookup_value","lookup":{"table_code":"TABB2","key_column":"stufe","value":"bakterien_erreichbar"}},{"key":"credit_abweichend","label":"abweichend (Referenzanlage / Nachweis)","type":"boolean"},{"key":"erwartbar_viren","label":"erwartbar Viren","type":"derived","expr":"lookup(''TABB2'', stufe, ''viren_erwartbar_text'')"},{"key":"erwartbar_protozoen","label":"erwartbar Protozoen","type":"derived","expr":"lookup(''TABB2'', stufe, ''protozoen_erwartbar_text'')"},{"key":"erwartbar_bakterien","label":"erwartbar Bakterien","type":"derived","expr":"lookup(''TABB2'', stufe, ''bakterien_erwartbar_text'')"},{"key":"ueberwachung_online","label":"Betriebsparameter online (Tab. 6)","type":"derived","expr":"lookup(''TAB6'', stufe, ''parameter_online'')"},{"key":"ueberwachung_periodisch","label":"Betriebsparameter periodisch (Tab. 6)","type":"derived","expr":"lookup(''TAB6'', stufe, ''parameter_periodisch'')"},{"key":"validierung_tab4","label":"Validierungsmethodik (Tab. 4)","type":"derived","expr":"lookup(''TAB4'', stufe, ''methodik'')"},{"key":"beispiel_e1","label":"Referenzanlage Schweinfurt — Betriebsbedingungen (Tab. E.1)","type":"derived","expr":"lookup(''TABE1_STUFEN'', stufe, ''betriebsbedingungen'')"},{"key":"auslegung","label":"Auslegungsparameter","type":"text"},{"key":"betriebsfenster_min","label":"Betriebsfenster min","type":"number","aria_label":"untere Grenze des Betriebsfensters"},{"key":"betriebsfenster_max","label":"Betriebsfenster max","type":"number","aria_label":"obere Grenze des Betriebsfensters"},{"key":"betriebsfenster_einheit","label":"Einheit","type":"text"}],"override":{"flag_key":"credit_abweichend","applies_to":["credit_viren","credit_protozoen","credit_bakterien"],"policy":"anhaltswert"},"footer":["stufen_count","credit_sum_viren","credit_sum_protozoen","credit_sum_bakterien"],"note":"2. Sofern keine Daten von Referenzanlagen vorliegen oder diese nicht anwendbar sind, können als Alternativvariante $\\log _{10}$-Reduktionen und Betriebsdaten aus weiteren Quellen herangezogen werden, die den Anforderungen der Dokumentation als Referenzanlage nach 3.3.5 genügen (insbesondere im Hinblick auf die Festlegung adäquater Betriebsparameter). Diese Daten müssen durch eine unabhängige Einrichtung oder die Genehmigungsbehörde nach 3.3.5 begutachtet werden. Zu den weiteren Quellen für $\\log _{10}$-Reduktionen und Betriebsdaten zählen beispielsweise technische Datenblätter von Lieferanten, veröffentlichte wissenschaftliche und technische Literatur (siehe z. B. die Zusammenstellung in Tabelle B. 1 im Anhang B), Leitlinien von Gesetzgebern (siehe z. B. die Australian Guidelines for Water Recycling (2006), die mit ergänzenden Angaben in Tabelle B. 2 im Anhang $B$ dargestellt sind) und historische Datenbestände von Anlagenbetreibern. Die einzelnen $\\log _{10}$-Reduktionen werden anschließend über den gesamten Aufbereitungszug aufsummiert."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verfahrenskette_stufen') AND w.code = 'M12002-12' AND s.code = 'DWA-M-1200-2';
