INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-13-B'), 'betriebsparameter', 'Betriebsparameter-Überwachung (Stufe nach Tab. 6, Parameter, Messhäufigkeit, Betriebsfenster, Alarmverzögerung)', 'json', NULL, false, '§6.4, Tab. 6; §3.3.3', 'Plan 3: Zeilen je überwachtem Betriebsparameter (TAB6-Zeile der Stufe mit den gedruckten Parametern / Häufigkeiten als Anzeige; eigene Messhäufigkeit als prod-Token; Betriebsfenster; Alarmverzögerung — SR-2: 5 min bis 30 min (L1289) als Text, geprüft wird das prod-Gate-Maximum 30); count / nicht online / max. Verzögerung → M12002-13-D1 … -D3; ersetzt die Skalare messhauefigkeit / alarm_verzoegerung_min (m1200_2-D-8); REQ-11 STAGED (m1200_2-G-6).', 'imported_unverified', 'Mit beiden Varianten werden die Mindestanforderungen an die Betriebsbedingungen für die Aufbereitungseinrichtung, insbesondere die relevanten Betriebsparameter und deren Anwendungsbereiche (Betriebsfenster) spezifiziert. Es sind mindestens die Betriebsparameter gemäß Tabelle 6 zu berücksichtigen. Hinweise zu relevanten Einflussfaktoren und relevanten Betriebsparametern können auch Tabelle 5 entnommen werden. Die spezifizierten Mindestanforderungen an die Betriebsparameter sind während der Inbetriebnahmephase und im Regelbetrieb einzuhalten. — \caption{Tabelle 6: Beispiel für Betriebsparameter und deren Messhäufigkeit zur Überwachung der zulässigen Betriebsbedingungen von ausgewählten Aufbereitungsstufen (Quelle: Australian Guidelines for Water Recycling 2020, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, mit Ergänzungen)} — Die Messhäufigkeit von Betriebsparametern muss die Systemträgheit berücksichtigen. Die Systemträgheit, evaluiert als hydraulische Verweilzeit, bestimmt die Dynamik für Gegenmaßnahmen, sodass kein Wasser der Wiederverwendung zugeführt wird, das die Anforderungen nicht erfüllt. Die regelmäßige Überprüfung der Betriebsparameter dient der Einhaltung der zulässigen Betriebsbedingungen und gewährleistet damit der Einhaltung der Qualitätsanforderungen und Leistungsziele. — Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen und Abweichungen vom zulässigen Betriebsfenster oder Havarien frühzeitig festzustellen, um Gegenmaßnahmen einzuleiten. Die Mess-wertaktualisierung/-abfrage sollte in der Regel wenige Minuten nicht überschreiten beziehungsweise die Systemträgheit widerspiegeln, um rechtzeitig Gegenmaßnahmen einzuleiten. Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen.', 'register', '{"title":"Betriebsparameter-Überwachung (Tab. 6)","subtitle":"§6.4 — je Betriebsparameter die Tab.-6-Zeile der Stufe, Messhäufigkeit, zulässiges Betriebsfenster und Alarmverzögerung (5 min bis 30 min nach L1289; REQ-11 liest ≤ 30 min)","add_label":"+ Parameter","placement":"section","columns":[{"key":"stufe","label":"Aufbereitungsstufe (Tab. 6)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB6"},"discriminator":true},{"key":"parameter_online","label":"Online-Parameter (Tab. 6)","type":"lookup_value","lookup":{"table_code":"TAB6","key_column":"stufe","value":"parameter_online"}},{"key":"parameter_periodisch","label":"Periodische Parameter (Tab. 6)","type":"lookup_value","lookup":{"table_code":"TAB6","key_column":"stufe","value":"parameter_periodisch"}},{"key":"frequenz_periodisch","label":"Häufigkeit periodisch (Tab. 6)","type":"lookup_value","lookup":{"table_code":"TAB6","key_column":"stufe","value":"frequenz_periodisch"}},{"key":"parameter","label":"Überwachter Parameter","type":"text","required":true},{"key":"messhaeufigkeit","label":"Messhäufigkeit","type":"enum","required":true,"options":["online","taeglich","woechentlich","monatlich"],"option_labels":{"online":"Online","taeglich":"Täglich","woechentlich":"Wöchentlich","monatlich":"Monatlich"}},{"key":"fenster_min","label":"Betriebsfenster min","type":"number","aria_label":"untere Alarmgrenze"},{"key":"fenster_max","label":"Betriebsfenster max","type":"number","aria_label":"obere Alarmgrenze"},{"key":"einheit","label":"Einheit","type":"text"},{"key":"alarm_verzoegerung_min","label":"Alarmverzögerung (5 bis 30 min)","type":"number","min":0,"unit":"min","aria_label":"Alarmverzögerung in Minuten"},{"key":"online_ok","label":"online","type":"derived","expr":"if(messhaeufigkeit == ''online'', 1, 0)","display":"badge","value_labels":{"0":"nicht online (L1287)","1":""}},{"key":"alarm_ok","label":"Alarm","type":"derived","expr":"if(alarm_verzoegerung_min IS NULL, 0, if(alarm_verzoegerung_min <= 30, 1, 0))","display":"badge","value_labels":{"0":"Alarmverzögerung fehlt oder > 30 min","1":""}}],"footer":["parameter_count","parameter_nicht_online","alarm_verzoegerung_max_calc"],"note":"Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen und Abweichungen vom zulässigen Betriebsfenster oder Havarien frühzeitig festzustellen, um Gegenmaßnahmen einzuleiten. Die Mess-wertaktualisierung/-abfrage sollte in der Regel wenige Minuten nicht überschreiten beziehungsweise die Systemträgheit widerspiegeln, um rechtzeitig Gegenmaßnahmen einzuleiten. Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'betriebsparameter') AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-13-D'), 'parameter_count', 'Anzahl überwachter Betriebsparameter', 'number', NULL, false, '§6.4, Tab. 6', 'Plan 3: Ausgabe der Gleichung M12002-13-D1 (count_rows über betriebsparameter).', 'imported_unverified', 'Mit beiden Varianten werden die Mindestanforderungen an die Betriebsbedingungen für die Aufbereitungseinrichtung, insbesondere die relevanten Betriebsparameter und deren Anwendungsbereiche (Betriebsfenster) spezifiziert. Es sind mindestens die Betriebsparameter gemäß Tabelle 6 zu berücksichtigen. Hinweise zu relevanten Einflussfaktoren und relevanten Betriebsparametern können auch Tabelle 5 entnommen werden. Die spezifizierten Mindestanforderungen an die Betriebsparameter sind während der Inbetriebnahmephase und im Regelbetrieb einzuhalten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'parameter_count') AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-13-D'), 'parameter_nicht_online', 'Betriebsparameter ohne Online-Messung', 'number', NULL, false, '§6.4', 'Plan 3: Ausgabe der Gleichung M12002-13-D2 (count_rows(online_ok == 0)); "Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand … zu allen Zeitpunkten sicherzustellen" (L1287); REQ-11 STAGED (m1200_2-G-6).', 'imported_unverified', 'Die Messhäufigkeit von Betriebsparametern muss die Systemträgheit berücksichtigen. Die Systemträgheit, evaluiert als hydraulische Verweilzeit, bestimmt die Dynamik für Gegenmaßnahmen, sodass kein Wasser der Wiederverwendung zugeführt wird, das die Anforderungen nicht erfüllt. Die regelmäßige Überprüfung der Betriebsparameter dient der Einhaltung der zulässigen Betriebsbedingungen und gewährleistet damit der Einhaltung der Qualitätsanforderungen und Leistungsziele.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'parameter_nicht_online') AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-13-D'), 'alarm_verzoegerung_max_calc', 'Größte Alarmverzögerung über die Betriebsparameter (Soll ≤ 30 min)', 'number', 'min', false, '§6.4', 'Plan 3: Ausgabe der Gleichung M12002-13-D3 (max_rows über betriebsparameter.alarm_verzoegerung_min, Zeilen mit Eintrag); Übernahme als alarm_verzoegerung_min / REQ-11 STAGED (m1200_2-D-8 / -G-6).', 'imported_unverified', 'Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen und Abweichungen vom zulässigen Betriebsfenster oder Havarien frühzeitig festzustellen, um Gegenmaßnahmen einzuleiten. Die Mess-wertaktualisierung/-abfrage sollte in der Regel wenige Minuten nicht überschreiten beziehungsweise die Systemträgheit widerspiegeln, um rechtzeitig Gegenmaßnahmen einzuleiten. Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'alarm_verzoegerung_max_calc') AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2';
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren IN {''mf'', ''uf'', ''mbr''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'messhauefigkeit_integritaet' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren IN {''mf'', ''uf'', ''nf'', ''uo'', ''mbr''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'transmembrandruck' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filtrationsverfahren IN {''mf'', ''uf'', ''nf'', ''uo'', ''mbr''}' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'permeatfluss' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''uv''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'uv_transmission' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''ozon''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'delta_sak254' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'desinfektionsverfahren == ''chlor''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'restchlor_freies' AND w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2' AND f.active;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'sekundaerdesinfektion_erforderlich == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'sekundaerdesinfektion_verfahren' AND w.code = 'M12002-14' AND s.code = 'DWA-M-1200-2' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-15-B'), 'kostenpositionen', 'Kostenpositionen je Verfahrensstufe (Kostenkennwert, Baupreisindex-Bezugsjahr; §8.2-Richtwerte als Hinweis)', 'json', NULL, false, '§8.2', 'Plan 3: Zeilen je Stufe (S8_2_KOSTEN-Zeile mit min / max als Hinweis, eigener Kostenkennwert, Bezugsjahr); Σ → kosten_summe_calc (M12002-15-D1); ersetzt das Skalar kostenkennwert_aufbereitung (m1200_2-D-9); REQ-14 bleibt.', 'imported_unverified', 'Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E :', 'register', '{"title":"Kostenpositionen je Verfahrensstufe (§8.2)","subtitle":"je Stufe der eigene Kostenkennwert in €/m³ Schmutzwasser; die gedruckten groben Richtwerte (Preisstand 2020) erscheinen als Hinweis, nie als Vorgabe (SR-2)","add_label":"+ Position","placement":"section","columns":[{"key":"stufe","label":"Stufe (§8.2)","type":"lookup_key","required":true,"lookup":{"table_code":"S8_2_KOSTEN"},"discriminator":true},{"key":"richtwert_min","label":"Richtwert min (€/m³ SW, 2020)","type":"lookup_value","lookup":{"table_code":"S8_2_KOSTEN","key_column":"stufe","value":"kosten_min_eur_m3"}},{"key":"richtwert_max","label":"Richtwert max (€/m³ SW, 2020)","type":"lookup_value","lookup":{"table_code":"S8_2_KOSTEN","key_column":"stufe","value":"kosten_max_eur_m3"}},{"key":"kostenkennwert","label":"Kostenkennwert","type":"number","required":true,"min":0,"unit":"€/m³ SW","aria_label":"eigener Kostenkennwert der Stufe"},{"key":"baupreisindex_jahr","label":"Baupreisindex-Bezugsjahr","type":"number","min":1900,"aria_label":"Bezugsjahr des Baupreisindex"},{"key":"im_richtwertbereich","label":"im Richtwertbereich","type":"derived","expr":"if(kostenkennwert >= richtwert_min AND kostenkennwert <= richtwert_max, 1, 0)","display":"badge","value_labels":{"0":"außerhalb des gedruckten Bereichs (Hinweis)","1":"im gedruckten Bereich"}}],"footer":["kosten_summe_calc"],"note":"Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \\mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E :"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kostenpositionen') AND w.code = 'M12002-15' AND s.code = 'DWA-M-1200-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'M12002-15-D'), 'kosten_summe_calc', 'Σ Kostenkennwerte über die Verfahrensstufen', 'number', '€/m³ SW', false, '§8.2', 'Plan 3: Ausgabe der Gleichung M12002-15-D1 (sum_rows über kostenpositionen.kostenkennwert — Text-Ableitung: §8.2 druckt Kosten je Stufe, keine Summenformel, m1200_2-F-1); Übernahme als kostenkennwert_aufbereitung STAGED (m1200_2-D-9).', 'imported_unverified', 'Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E :', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kosten_summe_calc') AND w.code = 'M12002-15' AND s.code = 'DWA-M-1200-2';
COMMIT;
